// single-item input: one query covers every title.
const cfg = $('Settings').first().json;
const body = $input.first().json || {};

// The API answers a bad parameter mix with HTTP 200 and an error object. The
// one that bites here is rvlimit with more than one title: "invalidparammix",
// green node, no revisions, no report, forever.
if (body.error) {
  throw new Error(
    'Wikipedia refused the query: ' + (body.error.code || '') + ' - ' +
    String(body.error.info || '').slice(0, 200)
  );
}

const q = body.query || {};
// formatversion=2 makes this an array. Without it, pages is an object keyed by
// page id and every read of it needs Object.values on an unpredictable number.
const pages = q.pages || [];

if (!pages.length) {
  throw new Error(
    'No pages came back at all. Check the language code in Settings - a wiki ' +
    'that does not exist answers with an empty query rather than an error.'
  );
}

// A redirect is followed silently, so the title asked for and the title read
// are not always the same. Storing the one that came back keeps next week's
// comparison stable.
const asked = {};
for (const r of q.redirects || []) asked[r.to] = r.from;

return pages.map(p => {
  const rev = (p.revisions || [])[0] || {};
  return {
    json: {
      source: 'wikipedia',
      entity: p.title,
      asked_as: asked[p.title] || p.title,
      // Not a 404. A page nobody has written comes back as an ordinary object
      // with missing: true, and that is indistinguishable from "no edits"
      // unless it is checked.
      exists: !p.missing,
      revid: rev.revid || 0,
      user: rev.user || '',
      timestamp: rev.timestamp || '',
      comment: rev.comment || '',
      size: rev.size || 0,
      tags: rev.tags || [],
    },
  };
});

// wbgetentities is keyed by entity id, so what you asked for is not in the
// answer. Measured with four titles, two of them real: the object came back
// with keys Q48818116, Q5926631, "-1" and "-2". A missing entity carries no
// title, no sitelink and nothing else to match it back, so the only reliable
// pairing is sitelinks.enwiki.title on the ones that exist, and the missing
// ones are whatever is left over.
//
// single-item input: one request covers every title.
const cfg = $('Settings').first().json;
const body = $input.first().json || {};

if (body.error) {
  throw new Error(
    'Wikidata refused the query: ' + (body.error.code || '') + ' - ' +
    String(body.error.info || '').slice(0, 200)
  );
}

const wiki = String(cfg.language || 'en') + 'wiki';
const asked = String(cfg.titles || '')
  .split(',').map(t => t.trim()).filter(Boolean);

const entities = body.entities || {};
const matched = new Set();
const out = [];

for (const key of Object.keys(entities)) {
  const e = entities[key];
  if (e.missing !== undefined || key.charAt(0) === '-') continue;

  const title = ((e.sitelinks || {})[wiki] || {}).title || '';
  if (title) matched.add(title);

  out.push({
    json: {
      source: 'wikidata',
      entity: title || key,
      qid: e.id || key,
      exists: true,
      revid: e.lastrevid || 0,
      timestamp: e.modified || '',
      user: '',
      comment: '',
      label: ((e.labels || {}).en || {}).value || '',
      description: ((e.descriptions || {}).en || {}).value || '',
    },
  });
}

for (const t of asked) {
  if (matched.has(t)) continue;
  out.push({
    json: {
      source: 'wikidata',
      entity: t,
      qid: '',
      exists: false,
      revid: 0,
      timestamp: '',
      user: '',
      comment: '',
      label: '',
      description: '',
    },
  });
}

return out;

// reads the table: $input is the stored history on purpose. The two wikis
// arrive through the merge above and are pulled by name, because a Data Table
// read replaces the item the same way a Set node does.
const cfg = $('Settings').first().json;
const lang = String(cfg.language || 'en');
const rows = $('Put The Two Wikis Together').all().map(i => i.json);

const history = {};
for (const item of $input.all()) {
  const r = item.json || {};
  if (r.source_key) history[String(r.source_key)] = r;
}

const wpHost = 'https://' + lang + '.wikipedia.org';
const out = [];

for (const r of rows) {
  const isWd = r.source === 'wikidata';
  const host = isWd ? 'https://www.wikidata.org' : wpHost;
  const key = isWd ? 'wikidata:' + r.entity : lang + 'wiki:' + r.entity;

  const prev = history[key];
  const before = prev ? Number(prev.revid) || 0 : 0;
  const now = Number(r.revid) || 0;

  let route = 'quiet';
  let state = 'unchanged';

  if (!r.exists) {
    state = 'no page';
    // Reported every run on purpose. Not having a page is not an event that
    // happens once - it is a standing state, and it is the whole point of
    // watching a brand rather than a page.
    route = 'no page';
  } else if (!prev) {
    state = 'first look';
  } else if (before !== now) {
    state = 'edited';
    route = 'edited';
  }

  // An edit can only be diffed against a revision already seen. On a first
  // look there is nothing to compare with, and pairing a revision with itself
  // answers 400.
  const compare = host + '/w/api.php?action=compare&fromrev=' + before +
    '&torev=' + now + '&prop=diff&format=json&formatversion=2';

  // A page that does not exist gets a search instead of a diff, so every item
  // on this path still carries a real request - and the answer is the useful
  // next step rather than a shrug.
  //
  // The two wikis need different searches. On Wikipedia, list=search returns
  // article titles, which answers "who already mentions us". On Wikidata,
  // list=search returns bare Q-ids; wbsearchentities returns the label and the
  // description, which answers the more interesting question: measured on
  // Ahrefs, no English article exists but Q107533769 does, described as a
  // "search engine optimization company". The item is there and nothing links
  // to it, which is exactly the state worth knowing about.
  const search = isWd
    ? host + '/w/api.php?action=wbsearchentities&language=' + lang +
      '&uselang=' + lang + '&limit=5&format=json&formatversion=2&search=' +
      encodeURIComponent(r.entity)
    : host + '/w/api.php?action=query&list=search&srlimit=5' +
      '&srsearch=' + encodeURIComponent(r.entity) +
      '&format=json&formatversion=2';

  out.push({
    json: {
      source_key: key,
      entity: r.entity,
      source: r.source,
      state,
      route,
      revid: now,
      previous_revid: before,
      user: r.user || '',
      timestamp: r.timestamp || '',
      comment: r.comment || '',
      size: r.size || 0,
      tags: r.tags || [],
      label: r.label || '',
      description: r.description || '',
      url: isWd
        ? (r.qid ? host + '/wiki/' + r.qid : host)
        : wpHost + '/wiki/' + encodeURIComponent(r.entity),
      fetch_url: route === 'edited' ? compare : search,
    },
  });
}

// A branch that can emit nothing ends there, and the store below it never
// runs. One marker keeps the quiet path alive on an empty configuration.
if (!out.length) {
  return [{ json: { source_key: '', state: 'nothing configured', route: 'quiet' } }];
}

return out;

// The fetches ran in the order the IF passed them through, and the IF preserves
// order, so body N belongs to non-quiet row N. Nothing in the compare response
// names the page it diffed, which is why the pairing is done by position and
// the filter here has to match the one the IF applied exactly.
const rows = $('What Changed Since').all().map(i => i.json)
  .filter(r => r.route !== 'quiet');

const bodies = $input.all().map(i => i.json);

function textOf(html) {
  return String(html || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#0?39;/g, "'")
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ')
    .trim();
}

// The Code sandbox has no DOM, so the diff cells come out by class name. Those
// classes are stable because they are what colours the diff on the wiki.
function cells(html, cls) {
  const out = [];
  const re = new RegExp(
    '<td[^>]*class="[^"]*' + cls + '[^"]*"[^>]*>([\\s\\S]*?)<\\/td>', 'g'
  );
  for (const m of String(html || '').matchAll(re)) {
    const t = textOf(m[1]);
    if (t) out.push(t);
  }
  return out;
}

const changes = [];
const missing = [];

for (let i = 0; i < rows.length; i += 1) {
  const r = rows[i];
  const body = bodies[i] || {};

  if (r.route === 'no page') {
    const articles = (((body.query || {}).search) || [])
      .map(h => h.title).slice(0, 5);
    const items = (body.search || [])
      .map(h => h.id + ' (' + (h.label || '') +
        (h.description ? ', ' + h.description : '') + ')')
      .slice(0, 3);
    missing.push({
      entity: r.entity,
      source: r.source,
      url: r.url,
      mentions: articles,
      lookalikes: items,
    });
    continue;
  }

  const html = ((body.compare || {}).body) || '';

  // A Wikidata edit summary is structured rather than prose:
  // /* wbsetaliases-add:2|pl */ semrush.com, sem rush. The operation is worth
  // more than the free text after it, so it is read out by name.
  const opMatch = String(r.comment || '').match(/\/\*\s*([a-z]+)-?([a-z]*)/);
  const op = opMatch ? opMatch[1] + (opMatch[2] ? '-' + opMatch[2] : '') : '';

  changes.push({
    entity: r.entity,
    source: r.source,
    url: r.url,
    user: r.user || '',
    timestamp: r.timestamp || '',
    comment: String(r.comment || '').slice(0, 200),
    operation: op,
    description: r.description || '',
    tags: r.tags || [],
    added: cells(html, 'diff-addedline').slice(0, 6).map(t => t.slice(0, 320)),
    removed: cells(html, 'diff-deletedline').slice(0, 6).map(t => t.slice(0, 320)),
    where: cells(html, 'diff-lineno').slice(0, 4),
    diff_failed: !!body.error,
  });
}

return [{
  json: {
    changes,
    change_count: changes.length,
    missing,
    missing_count: missing.length,
    for_model: changes.map(c => ({
      entity: c.entity,
      source: c.source,
      summary: c.comment,
      operation: c.operation,
      where: c.where,
      added: c.added,
      removed: c.removed,
    })),
  },
}];

// single-item input: one summary of the whole check.
const d = $('Read The Diffs').first().json;
const note = String($input.first().json.text || '').trim();
const NL = String.fromCharCode(10);
const lines = [];

// Counted by name, not by wiki: a brand missing from both produced two rows
// and read as two findings.
const missingNames = Array.from(new Set(d.missing.map(m => m.entity)));

lines.push('<p><b>' + d.change_count + ' edit' +
  (d.change_count === 1 ? '' : 's') + '</b> since the last check' +
  (missingNames.length
    ? ', and ' + missingNames.length +
      (missingNames.length === 1 ? ' name with a page missing' : ' names with pages missing')
    : '') + '.</p>');

for (const c of d.changes) {
  lines.push('<p><b>' + c.entity + '</b> - ' + c.source +
    (c.operation ? ' (' + c.operation + ')' : '') +
    '<br>by ' + (c.user || 'an editor') + ' on ' +
    String(c.timestamp).slice(0, 10) +
    (c.comment ? '<br><i>' + c.comment + '</i>' : '') + '</p>');

  if (c.removed.length) {
    lines.push('<p style="color:#a00">removed: ' +
      c.removed.map(x => x.slice(0, 240)).join('<br>') + '</p>');
  }
  if (c.added.length) {
    lines.push('<p style="color:#060">added: ' +
      c.added.map(x => x.slice(0, 240)).join('<br>') + '</p>');
  }
  if (!c.added.length && !c.removed.length) {
    lines.push('<p>The diff came back empty, so only the summary above is ' +
      'known. On Wikidata that usually means a qualifier or a reference ' +
      'moved rather than a value.</p>');
  }
  lines.push('<p><a href="' + c.url + '">' + c.url + '</a></p><hr>');
}

// Grouped by name rather than by wiki: a brand with neither page produced two
// rows saying the same thing, one for each source.
const byEntity = {};
for (const m of d.missing) {
  const g = byEntity[m.entity] || (byEntity[m.entity] =
    { sources: [], mentions: [], lookalikes: [] });
  g.sources.push(m.source);
  for (const x of m.mentions) if (g.mentions.indexOf(x) < 0) g.mentions.push(x);
  for (const x of m.lookalikes) if (g.lookalikes.indexOf(x) < 0) g.lookalikes.push(x);
}

for (const name of Object.keys(byEntity)) {
  const g = byEntity[name];
  lines.push('<p><b>' + name + '</b> has no ' + g.sources.join(' and no ') +
    ' page.' +
    (g.mentions.length
      ? ' Articles that already mention it: ' + g.mentions.join(', ') + '.'
      : '') +
    (g.lookalikes.length
      ? ' Wikidata items that look like it, none of them linked to an ' +
        'article: ' + g.lookalikes.join('; ') + '.'
      : '') + '</p>');
}

if (note) {
  lines.push('<hr><p><b>What to look at first</b></p><p>' +
    note.split(NL).join('<br>') + '</p>');
}

return [{
  json: {
    html: lines.join(NL),
    subject: d.change_count + ' edit' + (d.change_count === 1 ? '' : 's') +
      ' to what the sources say about you' +
      (missingNames.length
        ? ', and ' + missingNames.length + ' with a page missing'
        : ''),
  },
}];

// Every source, every run, whether or not it moved. A revision id written only
// in weeks with news cannot answer "changed since when".
const rows = $('What Changed Since').all().map(i => i.json)
  .filter(r => r.source_key);
const today = new Date().toISOString().slice(0, 10);

if (!rows.length) {
  return [{
    json: {
      source_key: 'nothing configured',
      entity: '',
      source: '',
      revid: 0,
      state: 'nothing configured',
      checked_on: today,
    },
  }];
}

return rows.map(r => ({
  json: {
    source_key: String(r.source_key),
    entity: String(r.entity || ''),
    source: String(r.source || ''),
    revid: Number(r.revid) || 0,
    state: String(r.state || ''),
    checked_on: today,
  },
}));
